-- Five-element variants. Existing variant IDs, ownership, decks and histories are retained.
begin;
alter table public.dv_card_definitions drop constraint if exists dv_card_definitions_element_check;
alter table public.dv_card_definitions add constraint dv_card_definitions_element_check check(element in ('fire','water','earth','air','storm','stone'));
update public.dv_card_definitions set element='earth' where element='stone';
alter table public.dv_card_variants add column if not exists element text;
update public.dv_card_variants v set element=d.element from public.dv_card_definitions d where v.definition_id=d.id and v.element is null;
alter table public.dv_card_variants drop constraint if exists dv_card_variants_definition_id_rarity_key;
on conflict(id) do update set name=excluded.name,element=excluded.element,edge_values=excluded.edge_values;
on conflict(id) do update set image=excluded.image,element=excluded.element;
update public.dv_card_variants set image='/game/assets/cards/frame-v21/swollen-doge.webp' where id='doge:common';
select v.id||':'||e.id,v.definition_id,v.rarity,v.image,v.edition,e.id
from public.dv_card_variants v join public.dv_card_definitions d on d.id=v.definition_id
cross join (values('fire'),('water'),('earth'),('air'),('storm')) e(id)
where v.element=d.element and e.id<>d.element and v.id=v.definition_id||':'||v.rarity
on conflict(id) do nothing;
alter table public.dv_card_variants alter column element set not null;
do $$begin if not exists(select 1 from pg_constraint where conname='dv_variant_element53') then alter table public.dv_card_variants add constraint dv_variant_element53 check(element in ('fire','water','earth','air','storm'));end if;end$$;
create unique index if not exists dv_variant_identity53 on public.dv_card_variants(definition_id,rarity,element);
-- Booster selection and crafting already operate on the persisted variant pool.
-- Their prices, rarity odds, guarantee, history and account permissions are unchanged.
create or replace function public.dv_initialize_account() returns void language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();fresh uuid;granted uuid;starter text[];
begin
 if u is null then raise exception 'Authentication required' using errcode='28000';end if;
 if granted is not null then
  on conflict(user_id,variant_id) do update set quantity=greatest(public.dv_inventory.quantity,excluded.quantity);
 end if;
 if fresh is not null then
  select array_agg(s.id order by s.n,g.i) into starter from (values('pepe:common',3,1),('doge:common',3,2),('roll-safe:common',3,3),('harold:common',2,4),('disaster-girl:common',2,5),('confused:common',2,6)) as s(id,quantity,n) cross join lateral generate_series(1,s.quantity) as g(i);
 end if;
end;$$;
commit;
